    s = re.sub('ae','ä',s)
    s = re.sub('OE','Ö',s)
    s = re.sub('Oe','Ö',s)
    s = re.sub('oe','ö',s)
    s = re.sub('UE','Ü',s)
    s = re.sub('Ue','Ü',s)
    s = re.sub('ue','ü',s)
    # eszett: 'ss' -> ß only when lower-case double s; approximate
    s = re.sub('ss','ß',s)
